def pm(n,title,pmid,pub,pmc=None):
    url=f"https://pmc.ncbi.nlm.nih.gov/articles/{pmc}/" if pmc else f"https://pubmed.ncbi.nlm.nih.gov/{pmid}/"
    how="PMC 전문 확인(PubMed 도구)" if pmc else "PubMed 초록 확인(PubMed 도구)"
    return {"n":n,"title":title+f" PMID {pmid}"+(f", {pmc}" if pmc else ""),"url":url,"publisher":f"{pub} ({how})","accessed":A}
